// Config used only by the post-merge commitlint job in commitlint.yml (push to main).
//
// A squash-merged commit is generated by GitHub from the PR title and body, so its
// body and footer are not hand-authored and cannot be edited once merged. Enforcing
// line-length rules on that generated text fails the push job permanently with no
// fix available (PR #682 produced such a commit on main). Author-written commits are
// still linted strictly by commitlint.config.cjs in the commit-msg hook, the pre-push
// hook and the PR job; the PR job also warns about body lines over 100 chars.
const base = require('./commitlint.config.cjs');

module.exports = {
  ...base,
  rules: {
    ...base.rules,
    'body-max-line-length': [0],
    'footer-max-length': [0],
    'footer-max-line-length': [0],
  },
};
